<?php declare(strict_types=1);namespace App\Controllers\Api;use App\Core\Request;use App\Core\Response;use App\Models\Plan;final class PlanController{public function index(Request $I):Response{$p=array_map([Plan::class,'toApi'],Plan::activePlans());return Response::json(['ok'=>true,'currency'=>(string)setting('billing.currency','EUR'),'plans'=>$p])->withHeader('Cache-Control','public, max-age=300');}}